def normalize_legacy_accounts(apps, schema_editor):
    User = apps.get_model("users", "User")
    Community = apps.get_model("users", "Community")
    Membership = apps.get_model("users", "CommunityMembership")
    database = schema_editor.connection.alias

    User.objects.using(database).all().update(email_verified=True)
    legacy_examiners = User.objects.using(database).filter(role="examiner").order_by("id")
    communities = {}
    for user in legacy_examiners:
        institution = (user.institution_name or "").strip()
        key = institution.casefold() if institution else f"user-{user.pk}"
        community = communities.get(key)
        if community is None:
            community = Community.objects.using(database).create(
                name=institution or f"Community for {user.full_name}",
                created_by_id=user.pk,
            )
            communities[key] = community
        Membership.objects.using(database).create(
            community_id=community.pk,
            user_id=user.pk,
            role="owner",
        )
    User.objects.using(database).filter(role__in=["student", "examiner"]).update(role="user")


